import sys


def find_min_index(nums):
    left, right = -1, len(nums) - 1
    while left + 1 < right:
        mid = (left + right) // 2
        if nums[mid] < nums[-1]:
            right = mid
        else:
            left = mid
    return right


def lower_bound(nums, left, right, target):
    # 在指定的开区间中二分，循环结束后验证候选下标。
    while left + 1 < right:
        mid = (left + right) // 2
        if nums[mid] >= target:
            right = mid
        else:
            left = mid
    return right if nums[right] == target else -1


def solve():
    n, target = map(int, sys.stdin.readline().split())
    nums = list(map(int, sys.stdin.readline().split()))

    split = find_min_index(nums)
    if target > nums[-1]:
        answer = lower_bound(nums, -1, split, target)
    else:
        # target 不大于末尾元素，所以候选下标不会越过数组末端。
        answer = lower_bound(nums, split - 1, n, target)

    print(answer)


if __name__ == '__main__':
    solve()

